import React, { useState } from 'react';
import '../Styles/style.css';

export default function Navbar() {
    const [isOpen, setIsOpen] = useState(false);

    // Fonction unique pour fermer proprement le menu
    const closeMenu = () => {
        setIsOpen(false);
    };

    return (
        <>
            <nav className="navbar">
                <div className="nav-logo" onClick={closeMenu}>
                    MonLogo
                </div>

                <button
                    className={`hamburger ${isOpen ? 'open' : ''}`}
                    onClick={() => setIsOpen(!isOpen)}
                    aria-label="Menu de navigation"
                >
                    <span className="bar"></span>
                    <span className="bar"></span>
                    <span className="bar"></span>
                </button>

                <div className={`nav-links ${isOpen ? 'active' : ''}`}>
                    <a href="#page1" onClick={closeMenu}>Page 1</a>
                    <a href="#page2" onClick={closeMenu}>Page 2</a>
                </div>
            </nav>

            {/* Voile noir en arrière-plan qui ferme au clic */}
            {isOpen && <div className="menu-overlay" onClick={closeMenu}></div>}
        </>
    );
}
